final class JsonTokenizer(pretty: Boolean = false) {
  private val printer = if (pretty) io.circe.Printer.spaces2 else io.circe.Printer.noSpaces

  def tokenize(value: Json): Token = {
    val jsonStr = printer.print(value)
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizePath(value: Json, path: String): Option[Token] = {
    val parts = path.split("\\.").toList.filter(_.nonEmpty)

    val result = parts.foldLeft(Option(value)) { (current, part) =>
      current.flatMap { json =>
        json.asObject.flatMap(_.apply(part))
          .orElse {
            json.asArray.flatMap { array =>
              if (part.forall(_.isDigit)) array.lift(part.toInt) else None
            }
          }
      }
    }

    result.map(tokenize)
  }
}

// ============================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// ============================================================================

final class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] = ".,!?;:'\"()[]{}".toSet

  private def stripPunct(word: String): String = {
    val leadingStripped = word.dropWhile(punctuation.contains)
    leadingStripped.reverse.dropWhile(punctuation.contains).reverse
  }

  private def processToken(word: String): Option[String] = {
    val stripped = if (stripPunctuation) stripPunct(word) else word
    val normalized = if (lowercase) stripped.toLowerCase else stripped

    if (normalized.length < minLength) None
    else {
      val truncated = maxLength match {
        case Some(max) if normalized.length > max => normalized.take(max)
        case _ => normalized
      }
      Option(truncated).filter(_.nonEmpty)
    }
  }

  def tokenize(text: String): List[Token] = {
    val trimmed = text.trim
    if (trimmed.isEmpty) return List.empty

    val words = trimmed.split("\\s+").toList

    words.zipWithIndex.flatMap { case (word, index) =>
      processToken(word).map { processed =>
        Token(
          value = processed,
          tokenType = TokenType.STRING,
          metadata = Map("position" -> index, "original" -> word)
        )
      }
    }
  }

  def tokenizeToStrings(text: String): List[String] =
    tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val trimmed = text.trim
    if (trimmed.isEmpty) return List.empty

    val words = trimmed.split("\\s+").toList
    val result = mutable.ListBuffer.empty[(String, Int, Int)]
    var currentPos = 0

    words.foreach { word =>
      val start = text.indexOf(word, currentPos)
      val end = if (start < 0) start else start + word.length

      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }

      currentPos = if (end < 0) currentPos else end
    }

    result.toList
  }

  def countTokens(text: String): Int = tokenize(text).length
}

